sed -i 's/let audioBuffer: AudioBuffer; if (asset.audioUrl) { try { const response = await fetch(asset.audioUrl); const arrayBuffer = await response.arrayBuffer(); audioBuffer = await audioCtx.decodeAudioData(arrayBuffer); } catch (e) { const duration = asset.narration ? Math.max(2, asset.narration.length \* 0.2) : 4; audioBuffer = audioCtx.createBuffer(1, 24000 \* duration, 24000); } } else { const duration = asset.narration ? Math.max(2, asset.narration.length \* 0.2) : 4; audioBuffer = audioCtx.createBuffer(1, 24000 \* duration, 24000); }/let audioBuffer: AudioBuffer | null = null;\n        if (asset.audioUrl) {\n            try {\n                const response = await fetch(asset.audioUrl);\n                const arrayBuffer = await response.arrayBuffer();\n                audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);\n            } catch (e) {\n                console.error("Failed to load audioUrl", e);\n            }\n        }\n\n        let videoAudioBuffer: AudioBuffer | null = null;\n        if (asset.assetType === '\''video'\'' \&\& asset.url) {\n            try {\n                const response = await fetch(asset.url);\n                const arrayBuffer = await response.arrayBuffer();\n                videoAudioBuffer = await audioCtx.decodeAudioData(arrayBuffer);\n            } catch (e) {\n                console.log("No audio track in video or failed to decode");\n            }\n        }\n\n        let duration = 4;\n        if (audioBuffer) duration = audioBuffer.duration;\n        else if (videoAudioBuffer) duration = videoAudioBuffer.duration;\n        else if (asset.narration) duration = Math.max(2, asset.narration.length * 0.2);\n\n        let mainAudioBuffer = audioBuffer;\n        if (!mainAudioBuffer) {\n            mainAudioBuffer = audioCtx.createBuffer(1, 24000 * duration, 24000);\n        }\n/' components/VideoProductionPanel.tsx
